"C:\\Users\\ww\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -NoProfile -Command '$taskCurrentDirectory = (Get-Location).Path
Write-Output ('"'CurrentDirectory: ' + "'$taskCurrentDirectory)
$taskPaths = @('"'.agents/skills/cineweave-director/SKILL.md', '.agents/skills/cineweave-director/references/optional/video-platform-adaptation.md', '.agents/skills/cineweave-director/references/optional/video-model-practices-2026-10.md')
"'$taskResults = foreach ($taskPath in $taskPaths) {
    $taskHash = Get-FileHash -LiteralPath $taskPath -Algorithm SHA256 -ErrorAction Stop
    $taskText = Get-Content -LiteralPath $taskPath -Raw -Encoding UTF8 -ErrorAction Stop
    [PSCustomObject]@{
        Path = $taskHash.Path
        SHA256 = $taskHash.Hash
        UFFFDCount = ([regex]::Matches($taskText, [string][char]0xFFFD)).Count
    }
}
$taskResults | ConvertTo-Json -Depth 3'

